//! Extension grammar rules — the productions nanopython adds on top of
//! vendor `py/grammar.h`.
//!
//! `grammar_data.zig` is generated from vendor grammar.h and pinned by
//! SHA-256; vendor/ is regenerated by `make port` and must not be
//! hand-edited. So rules we add live here instead, in ids NUM_RULES..255
//! (rule ids are u8 and vendor stops at 183), and the parser widens its
//! two table lookups to consult this file above that boundary. The
//! generated file stays byte-identical to the C shim.
//!
//! Extension rules run on the unmodified parser engine: same act/arg
//! encoding, same AND/OR/LIST handling, same node building.
//!
//! ── The match statement ──────────────────────────────────────────────
//!
//! `match` and `case` are soft keywords with no TokenKind of their own
//! (see lexer.zig's SOFT KEYWORDS section), so both rules start on a
//! bare `tok(NAME)`. That is only sound because the sole entry point is
//! the parser's soft-keyword hook, which has already checked the text
//! and confirmed a trailing ':' via peekLineEndsWithColon(). Nothing
//! reaches match_stmt by ordinary alternative-matching.
//!
//! Patterns are parsed as *expressions* rather than given a pattern
//! grammar of their own. CPython needs one because PEG wants precision;
//! we don't, because every pattern form except two is already a valid
//! expression:
//!
//!     case 1:            literal    -> expr
//!     case x:            capture    -> expr (NAME)
//!     case 1 | 2:        or-pattern -> expr ('|' is bitwise-or level)
//!     case [a, *rest]:   sequence   -> exprlist_2 (star_expr | expr)
//!     case P(x=1):       class      -> expr (call with keywords)
//!     case {'k': v}:     mapping    -> expr (dict display)
//!
//! The two that aren't expressions get a rule each: `as` bindings and
//! `if` guards. Interpreting the resulting expression tree as a pattern
//! is the compiler's job.

const grammar = @import("grammar_data.zig");
const lexer = @import("lexer.zig");

/// Rule ids continue where the generated table stops.
pub const RULE_match_stmt: u8 = @intCast(grammar.NUM_RULES);
pub const RULE_match_stmt_case_list: u8 = RULE_match_stmt + 1;
pub const RULE_match_stmt_case: u8 = RULE_match_stmt + 2;
pub const RULE_match_stmt_patterns: u8 = RULE_match_stmt + 3;
pub const RULE_match_stmt_pattern: u8 = RULE_match_stmt + 4;
pub const RULE_match_stmt_alts: u8 = RULE_match_stmt + 5;
pub const RULE_match_stmt_alt: u8 = RULE_match_stmt + 6;
pub const RULE_match_stmt_as: u8 = RULE_match_stmt + 7;
pub const RULE_match_stmt_guard: u8 = RULE_match_stmt + 8;

pub const NUM_EXT_RULES: usize = 9;
pub const LAST_RULE: usize = grammar.NUM_RULES + NUM_EXT_RULES;

// Mirrors the DEF_RULE macros in vendor grammar.h — see parse.c:79-85.
const or_ = grammar.RULE_ACT_OR;
const and_ = grammar.RULE_ACT_AND;
const list_ = grammar.RULE_ACT_LIST;
const ident = grammar.RULE_ACT_ALLOW_IDENT;
const one_or_more: u8 = list_ | 2;
const list_no_end: u8 = list_ | 1;

inline fn tok(t: lexer.TokenKind) u16 {
    return grammar.RULE_ARG_TOK | @as(u16, @intFromEnum(t));
}
inline fn rule(id: u8) u16 {
    return grammar.RULE_ARG_RULE | @as(u16, id);
}
inline fn opt(id: u8) u16 {
    return grammar.RULE_ARG_OPT_RULE | @as(u16, id);
}

// match_stmt: NAME namedexpr_test ':' NEWLINE INDENT case+ DEDENT
const args_match_stmt = [_]u16{
    tok(.NAME),
    rule(grammar.RULE_namedexpr_test),
    tok(.DEL_COLON),
    tok(.NEWLINE),
    tok(.INDENT),
    rule(RULE_match_stmt_case_list),
    tok(.DEDENT),
};
const args_case_list = [_]u16{rule(RULE_match_stmt_case)};
// case: NAME patterns [guard] ':' suite
const args_case = [_]u16{
    tok(.NAME),
    rule(RULE_match_stmt_patterns),
    opt(RULE_match_stmt_guard),
    tok(.DEL_COLON),
    rule(grammar.RULE_suite),
};
// patterns: pattern (',' pattern)*   — no trailing comma, matching
// CPython's open_sequence_pattern.
const args_patterns = [_]u16{ rule(RULE_match_stmt_pattern), tok(.DEL_COMMA) };
// pattern: alts ['as' NAME]
const args_pattern = [_]u16{ rule(RULE_match_stmt_alts), opt(RULE_match_stmt_as) };
// alts: alt ('|' alt)*
//
// The `|` has to be consumed HERE, not left to `expr`. Vendor's parser
// folds constant binary ops as it builds nodes (parser.zig
// foldSmallIntBinOp), so `case 1 | 2:` routed through `expr` arrives at
// the compiler as the small int 3 — an or-pattern silently turned into
// a bitwise-or. Binding `|` at this level, over `xor_expr` (the
// precedence rung below `|`), keeps the alternatives apart.
const args_alts = [_]u16{ rule(RULE_match_stmt_alt), tok(.OP_PIPE) };
const args_alt = [_]u16{ rule(grammar.RULE_star_expr), rule(grammar.RULE_xor_expr) };
const args_as = [_]u16{ tok(.KW_AS), tok(.NAME) };
const args_guard = [_]u16{ tok(.KW_IF), rule(grammar.RULE_namedexpr_test) };

const ext_act = [NUM_EXT_RULES]u8{
    and_ | 7, // match_stmt
    one_or_more, // case_list
    and_ | 5, // case
    list_no_end | 2, // patterns
    and_ | 2 | ident, // pattern — collapses to the bare alt when no `as`
    list_no_end | 2, // alts — collapses to the bare alt when no `|`
    or_ | 2, // alt
    and_ | 2, // as    — no ident: stays a node so the compiler can
    and_ | 2, // guard   test for it by kind rather than by position
};

const ext_args = [NUM_EXT_RULES][]const u16{
    &args_match_stmt,
    &args_case_list,
    &args_case,
    &args_patterns,
    &args_pattern,
    &args_alts,
    &args_alt,
    &args_as,
    &args_guard,
};

pub inline fn isExt(id: u8) bool {
    return id >= grammar.NUM_RULES;
}

/// Widened `grammar.ruleAct` — vendor table below NUM_RULES, ours above.
pub inline fn ruleAct(id: u8) u8 {
    return if (isExt(id)) ext_act[id - grammar.NUM_RULES] else grammar.ruleAct(id);
}

/// Widened `grammar.getRuleArg`.
pub inline fn getRuleArg(id: u8) [*]const u16 {
    return if (isExt(id)) ext_args[id - grammar.NUM_RULES].ptr else grammar.getRuleArg(id);
}

comptime {
    // Rule ids are u8 everywhere (parser.zig pushRule, Pn struct kinds).
    if (LAST_RULE > 256) @compileError("extension rule ids overflow u8");
    // Each act's arg count must match the arg array it indexes, or the
    // parser walks off the end of the slice.
    for (ext_act, ext_args, 0..) |act, args, i| {
        const n = act & grammar.RULE_ACT_ARG_MASK;
        const want = switch (act & grammar.RULE_ACT_KIND_MASK) {
            // LIST acts encode repetition in the low bits, not an arg
            // count: `one_or_more` takes 1 arg, the others 2.
            list_ => if (act == one_or_more) 1 else 2,
            else => n,
        };
        if (args.len != want) {
            @compileError("ext rule " ++ .{'0' + i} ++ " arg count mismatch");
        }
    }
}
